UPDATE "ShopCatalogItem" AS item
SET
  "name" = data."name",
  "costXp" = data."costXp",
  "resource" = data."resource",
  "rankHint" = data."rankHint",
  "description" = data."description",
  "effect" = data."effect",
  "updatedAt" = CURRENT_TIMESTAMP
FROM (
  VALUES
    ('relique-tete-trois-faces', 'Fragment de statuette étrange', 100, 'Fragment 1/5', 'Relique unique', 'Tête aux traits horrifiques, taillée dans un bois sombre et laqué. Elle possède trois visages : celui de gauche pleure, celui du milieu sourit et celui de droite arbore une expression de colère.', 'La tête peut s''enchâsser dans un buste compatible.'),
    ('relique-buste-triangle-cercle', 'Fragment de statuette étrange', 100, 'Fragment 2/5', 'Relique unique', 'Thorax humanoïde taillé dans un bois sombre et laqué. Un symbole est incrusté dans son abdomen : un triangle inversé inscrit dans un cercle. Plusieurs cavités et jointures sont visibles à ses extrémités.', 'Le buste peut accueillir quatre autres fragments : une tête, deux bras et des membres inférieurs.'),
    ('relique-bras-droit-xxx', 'Fragment de statuette étrange', 100, 'Fragment 3/5', 'Relique unique', 'Bras droit taillé dans un bois sombre et laqué. Ses doigts crochus se referment autour d''un vajra miniature, impossible à détacher de la paume.', 'Le bras droit peut s''enchâsser dans un buste compatible.'),
    ('relique-bras-gauche-globe', 'Fragment de statuette étrange', 100, 'Fragment 4/5', 'Relique unique', 'Bras gauche taillé dans un bois sombre et laqué. Ses doigts crochus soutiennent un globe miniature parfaitement sphérique, figé dans sa paume.', 'Le bras gauche peut s''enchâsser dans un buste compatible.'),
    ('relique-quatre-jambes', 'Fragment de statuette étrange', 100, 'Fragment 5/5', 'Relique unique', 'Membres inférieurs taillés dans un bois sombre et laqué. Leur anatomie évoque étrangement celle d''un cheval : quatre jambes maigres prolongent un même corps équin.', 'Les membres inférieurs peuvent s''enchâsser dans un buste compatible.'),

    ('conte-ichibi', 'Toile du Monstre-Tanuki', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Ichibi. La créature y apparaît sous les traits d''un monstrueux tanuki, couverte de marques sombres dont le peintre s''est appliqué à reproduire chaque contour. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue d''Ichibi. Débloque la moitié des informations consacrées à Ichibi dans le Wiki.'),
    ('conte-nibi', 'Toile du Chat-Fantôme', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Nibi. La créature y apparaît sous les traits d''un immense félin aux formes presque spectrales, dont la silhouette semble onduler sous les pigments employés par le peintre. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Nibi. Débloque la moitié des informations consacrées à Nibi dans le Wiki.'),
    ('conte-sanbi', 'Toile de la Géante-Tortue', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Sanbi. La créature y apparaît sous les traits d''une tortue titanesque, bardée d''une carapace que le peintre représente assez vaste pour émerger seule au-dessus des eaux. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Sanbi. Débloque la moitié des informations consacrées à Sanbi dans le Wiki.'),
    ('conte-yonbi', 'Toile du Roi-Singe', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Yonbi. La créature y apparaît sous les traits d''un singe colossal, dressé dans une posture souveraine au milieu d''un paysage rendu minuscule par sa stature. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Yonbi. Débloque la moitié des informations consacrées à Yonbi dans le Wiki.'),
    ('conte-gobi', 'Toile du Cheval-Baleine', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Gobi. La créature y apparaît sous les traits d''une chimère gigantesque mêlant les formes du cheval à celles de la baleine, une étrangeté que le peintre semble avoir reproduite avec une précision presque anatomique. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Gobi. Débloque la moitié des informations consacrées à Gobi dans le Wiki.'),
    ('conte-rokubi', 'Toile de la Folle-Limace', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Rokubi. La créature y apparaît sous les traits d''une limace monstrueuse, dont le corps difforme serpente à travers la composition dans un entrelacs de mucus, de membres et de queues. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Rokubi. Débloque la moitié des informations consacrées à Rokubi dans le Wiki.'),
    ('conte-nanabi', 'Toile du Scarabée-Psychopompe', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Nanabi. La créature y apparaît sous les traits d''un gigantesque insecte cuirassé, représenté en plein vol au-dessus d''une procession de silhouettes minuscules. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Nanabi. Débloque la moitié des informations consacrées à Nanabi dans le Wiki.'),
    ('conte-hachibi', 'Toile du Taureau-Poulpe', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Hachibi. La créature y apparaît sous les traits d''un taureau gigantesque dont le corps se prolonge en tentacules démesurés, entortillés autour des reliefs environnants. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Hachibi. Débloque la moitié des informations consacrées à Hachibi dans le Wiki.'),
    ('conte-kyuubi', 'Toile du Démon-Renard', 50, 'Conte bijû', 'Archive unique', 'Toile de vélin soigneusement enroulée, préservée des affres du temps, qui met en scène l''imposant Kyûbi. La créature y apparaît sous les traits d''un renard monstrueux dont les neuf queues occupent presque entièrement la composition. Au dos, quelques informations éparses s''agglutinent autour d''un nom.', 'Révèle l''apparence physique, le nom et une particularité générale connue de Kyûbi. Débloque la moitié des informations consacrées à Kyûbi dans le Wiki.'),
    ('conte-sage-senju', 'Conte du Premier Explorateur', 50, 'Conte clanique', 'Archive unique', 'Conte remanié par des générations de conteurs qui prétend conserver le souvenir d''un Homme ayant marché là où nul autre n''osait encore s''aventurer. Les lieux changent selon les versions, les exploits s''exagèrent et son visage s''est perdu ; quelque part sous ces embellissements subsiste pourtant l''histoire des premiers Otsutsuki.', 'Le conte permet d''obtenir le nom ainsi qu''un bref aperçu de l''Histoire du Premier Senju.'),
    ('conte-sage-uchiha', 'Conte de la Jumelle-Songe', 50, 'Conte clanique', 'Archive unique', 'Conte cryptique, alambiqué, transmis de génération en génération sous des formes parfois contradictoires. Il raconte l''existence de deux figures que les récits disent inséparables, jusqu''à ce que leurs chemins divergent et que l''une d''elles disparaisse derrière les songes ; quelque part sous ces mensonges subsiste pourtant l''histoire des premiers Otsutsuki.', 'Le conte permet d''obtenir le nom ainsi qu''un bref aperçu de l''Histoire de la Première Uchiha.'),
    ('conte-sage-sarutobi', 'Conte du Maître des Souffles', 50, 'Conte clanique', 'Archive unique', 'Conte immémorial passé de bouche en bouche, dont les mots, les noms et jusqu''au sens furent altérés par ceux qui le transmirent. Ses différentes versions évoquent un Homme qui aurait appris à écouter les souffles du monde, à reconnaître leurs caprices et à en tirer un enseignement que ses descendants auraient longtemps conservé ; quelque part sous ces interprétations subsiste pourtant l''histoire des premiers Otsutsuki.', 'Le conte permet d''obtenir le nom ainsi qu''un bref aperçu de l''Histoire du Premier Sarutobi.'),
    ('conte-sage-uzumaki', 'Conte du Ressuscité', 50, 'Conte clanique', 'Archive unique', 'Conte funèbre dont nul ne connaît plus l''auteur, récité depuis suffisamment longtemps pour que la mort et la naissance s''y confondent. Il raconte qu''un Homme aurait franchi une frontière dont personne ne revient, avant de reparaître parmi les vivants changé par ce qu''il avait rencontré de l''autre côté ; quelque part sous ces miracles subsiste pourtant l''histoire des premiers Otsutsuki.', 'Le conte permet d''obtenir le nom ainsi qu''un bref aperçu de l''Histoire du Premier Uzumaki.'),
    ('conte-sage-hyuga', 'Conte de la Jumelle-Vérité', 50, 'Conte clanique', 'Archive unique', 'Conte cryptique, alambiqué, transmis de génération en génération sous des formes parfois contradictoires. Il raconte l''existence de deux figures que les récits disent inséparables, jusqu''à ce que leurs chemins divergent et que l''une d''elles disparaisse derrière la vérité ; quelque part sous ces contradictions subsiste pourtant l''histoire des premiers Otsutsuki.', 'Le conte permet d''obtenir le nom ainsi qu''un bref aperçu de l''Histoire de la Première Hyuga.'),

    ('bombe-fumigene', 'Bombe fumigène', 10, 'Dissimulation', 'Consommable', 'Sphère violette qui dégage constamment une odeur exécrable. Lorsqu''elle rencontre un obstacle, elle éclate dans un claquement sec et libère un épais smog opaque.', 'Le brouillard constitue une dissimulation de zone du rang du personnage. Utiliser cet outil ne dépense pas une action.'),
    ('bombe-aveuglante', 'Bombe aveuglante', 10, 'Aveuglement', 'Consommable', 'Petite sphère métallique dont la surface est percée de plusieurs ouvertures. Lorsqu''elle rencontre un obstacle, elle éclate dans un claquement sec et libère un flash de lumière particulièrement intense.', 'L''éblouissement constitue un aveuglement de zone comptant comme une immobilisation partielle du rang du personnage. Utiliser cet outil ne dépense pas une action.'),
    ('kit-soin', 'Kit de soin', 10, 'Soin', 'Consommable', 'Petite sacoche contenant le nécessaire pour prodiguer des soins d''urgence : bandages, compresses, désinfectants, aiguilles, fils de suture, onguents médicinaux et stimulants.', 'Les soins résorbent une blessure d''un rang inférieur ou égal à celui du personnage. Utiliser cet outil ne dépense pas une action.'),
    ('parchemin-explosif', 'Parchemin explosif', 10, 'Explosion', 'Consommable', 'Bande de papier frappée d''une formule explosive, dont l''inscription s''embrase quelques instants avant la détonation. Le parchemin peut être apposé sur une surface ou lancé directement vers une cible.', 'L''explosion constitue une attaque de zone du rang du personnage. Utiliser cet outil ne dépense pas une action.'),
    ('chausse-trappes', 'Chausse-trappes', 10, 'Entrave', 'Consommable', 'Poignée de petites pointes métalliques conçues de sorte que l''une d''elles demeure toujours orientée vers le haut. Dispersées sur le terrain, elles rendent toute traversée particulièrement périlleuse.', 'Les pièges constituent une immobilisation partielle de zone. Utiliser cet outil ne dépense pas une action.'),
    ('sceau-alarme', 'Sceau d''alarme', 10, 'Détection', 'Consommable', 'Petit parchemin adhésif couvert d''inscriptions sensorielles. Une fois apposé sur une surface, le sceau réagit aux présences qui pénètrent dans son périmètre et émet une brève pulsation.', 'Le sceau constitue une détection de zone et révèle les cibles dissimulées présentes dans son périmètre. Utiliser cet outil ne dépense pas une action.'),
    ('antidote-universel', 'Antidote universel', 10, 'Antidote', 'Consommable', 'Petite fiole contenant un liquide translucide à l''amertume prononcée. Sa composition associe plusieurs agents capables de ralentir, puis de neutraliser, la plupart des toxines connues.', 'L''antidote neutralise un empoisonnement d''un rang inférieur ou égal à celui du personnage. Utiliser cet outil ne dépense pas une action.'),
    ('stimulant-tetsujin', 'Stimulant inconnu', 30, 'Stimulant', 'Usage RP unique', 'Petite ampoule contenant un liquide rougeâtre à l''odeur âcre. Une fois ingéré, le stimulant provoque une accélération brutale du rythme cardiaque, aiguise momentanément les réflexes et pousse l''organisme au-delà de sa cadence habituelle.', 'Le stimulant confère +1 action bonus pendant un tour. Utiliser cet outil ne dépense pas une action. Attention à l''overdose.'),
    ('grigri-sablonneux', 'Grigri mordoré', 30, 'Taiyō no Chi', 'Protection durable', 'Petit talisman de toile rêche rempli d''un sable anormalement froid, porté autour du cou par une cordelette tressée. Sous les chaleurs écrasantes de Taiyō no Chi, ses grains absorbent progressivement la température corporelle et demeurent frais même sous un soleil de plomb.', 'Le grigri protège son porteur des chaleurs extrêmes de Taiyō no Chi et lui permet d''y réaliser des RP sans subir les dangers liés à la température.'),
    ('dent-de-requin', 'Dent-de-Requin', 30, 'Umi no Chi', 'Protection durable', 'Énorme dent de squale percée à sa racine et montée sur un cordon marin. Elle exhale une odeur imperceptible pour l''Homme, mais suffisamment familière aux créatures des profondeurs pour détourner les super-prédateurs rôdant dans les eaux d''Umi no Chi.', 'La Dent-de-Requin protège son porteur des super-prédateurs marins d''Umi no Chi et lui permet d''y réaliser des RP sans craindre leurs assauts.'),
    ('tenue-militaire', 'Treillis nomade', 30, 'Hai no Chi', 'Protection durable', 'Uniforme réglementaire récupéré sur les anciennes forces armées de Hai no Chi. Manteau épais, protections sommaires, insignes, paquetage et couvre-chef composent une silhouette suffisamment reconnaissable pour être confondue, à distance, avec celle des combattants qui sillonnent encore les étendues de la contrée.', 'La tenue militaire protège son porteur des assauts nomades de Hai no Chi et lui permet d''y réaliser des RP sans craindre leurs attaques.'),
    ('combinaison-hazmat', 'Combinaison Hazmat', 30, 'Numa no Chi', 'Protection durable', 'Combinaison intégrale hermétique renforcée par des gants, des bottes et un masque filtrant. Ses différentes couches isolent entièrement le porteur de l''air vicié, des eaux stagnantes et des substances toxiques qui contaminent Numa no Chi.', 'La combinaison protège son porteur des poisons environnementaux de Numa no Chi et lui permet d''y réaliser des RP sans subir les effets de la contamination.'),

    ('gantelet-shinobi', 'Gantelet Shinobi', 30, 'Kekkei Genkai', 'Village C', 'Gantelet technique conçu pour accueillir des mini-rouleaux shinobi et canaliser des applications empruntées à un autre Kekkei Genkai.', 'Permet d''acheter une action d''un autre Kekkei Genkai. Cette ouverture explique la tarification majorée.'),
    ('mini-rouleaux-unique-durable-chargee', 'Mini-rouleaux shinobi : action unique/durable ou chargée', 30, 'Action KG', 'Village C', 'Mini-rouleaux compatibles avec le Gantelet Shinobi, préparés pour contenir une action simple, durable ou chargée issue d''un autre Kekkei Genkai.', 'Permet d''acheter une action unique, durable ou chargée d''un autre Kekkei Genkai.'),
    ('mini-rouleaux-combinee-complexe', 'Mini-rouleaux shinobi : action combinée ou complexe', 50, 'Action KG', 'Village C', 'Mini-rouleaux compatibles avec le Gantelet Shinobi, renforcés pour supporter une structure technique combinée ou complexe.', 'Permet d''acheter une action combinée ou complexe d''un autre Kekkei Genkai.'),
    ('mini-rouleaux-ultime', 'Mini-rouleaux shinobi : action ultime', 60, 'Action KG', 'Village C', 'Mini-rouleaux compatibles avec le Gantelet Shinobi, scellés pour contenir une application de très haut niveau.', 'Permet d''acheter une action ultime d''un autre Kekkei Genkai.'),
    ('mini-rouleaux-supreme', 'Mini-rouleaux shinobi : action suprême', 110, 'Action KG', 'Village C', 'Mini-rouleaux compatibles avec le Gantelet Shinobi, préparés pour accueillir les formes les plus exigeantes d''un art emprunté.', 'Permet d''acheter une action suprême d''un autre Kekkei Genkai.'),

    ('carte-isshin', 'Carte d''Isshin', 30, 'Contrée étrangère', 'Renseignement', 'Carte géographique dressée par le Voyageur aux Cent Horizons, et régulièrement enrichie au gré de ses pérégrinations. Reliefs, routes, frontières, lieux remarquables et annotations manuscrites s''entremêlent sur un papier épais dont les marges portent encore les observations de ses précédents détenteurs.', 'La carte permet d''obtenir une information contextuelle supplémentaire au sujet d''une Contrée étrangère.'),
    ('avis-recherche', 'Avis de recherche', 50, 'La Troupe', 'Renseignement', 'Feuillet officiel frappé du portrait et du signalement d''un individu recherché. Plusieurs annotations ajoutées à la main compilent témoignages, rumeurs, passages remarqués et dernières traces connues de la cible.', 'L''avis de recherche permet d''obtenir une information concernant la localisation actuelle ou récente d''un membre de la Troupe.'),

    ('lettre-cachetee-jdc', 'Invitation interlope', 100, 'Accès JDC', 'Trame unique', 'Enveloppe noire dépourvue d''expéditeur, de destinataire et de toute indication permettant d''en retracer l''origine. Un cachet de cire écarlate en interdit l''ouverture ; lorsqu''il est brisé, quelques lignes manuscrites apparaissent aux côtés d''un lieu, d''une heure et d''un nom : le tien.', 'La lettre confère un accès nominatif à la Trame Jeu du Calmar, ainsi qu''à la Boutique du Marché Noir. Elle ne peut être utilisée que par le personnage dont le nom figure sur l''invitation.'),

    ('reduction-marchandises-vie', 'Carte de fidélité', 300, 'Boutique', 'Service permanent', 'Petite carte nominative réservée aux clients les plus assidus de la Boutique. Son détenteur n''a manifestement plus besoin de négocier : son nom suffit désormais à faire baisser les prix avant même qu''il ne pose ses XP sur le comptoir.', 'La carte accorde définitivement une réduction de 25 % sur l''ensemble des marchandises de la Boutique.'),
    ('reconquete-contree-300', 'Droit de conquête - palier 300', 300, 'Contrée perdue', 'Palier Reconquête 1', 'Acte territorial frappé du sceau de la Grande Veilleuse et volontairement laissé incomplet. Frontières, administration, identité et devenir du territoire attendent encore d''être consignés : seule une ancienne dénomination, désormais rayée, rappelle que cette terre appartenait autrefois à d''autres.', 'Le droit permet de reconquérir instantanément une Contrée perdue au choix au bénéfice de Konoha. La communauté dispose ensuite d''une liberté totale pour définir collectivement son nouveau nom, sa description et son illustration. Son coût augmente de 300 XP après chaque reconquête.'),
    ('reconquete-contree-600', 'Droit de conquête - palier 600', 600, 'Contrée perdue', 'Palier Reconquête 2', 'Acte territorial frappé du sceau de la Grande Veilleuse et volontairement laissé incomplet. Frontières, administration, identité et devenir du territoire attendent encore d''être consignés : seule une ancienne dénomination, désormais rayée, rappelle que cette terre appartenait autrefois à d''autres.', 'Le droit permet de reconquérir instantanément une Contrée perdue au choix au bénéfice de Konoha. La communauté dispose ensuite d''une liberté totale pour définir collectivement son nouveau nom, sa description et son illustration. Son coût augmente de 300 XP après chaque reconquête.'),
    ('reconquete-contree-900', 'Droit de conquête - palier 900', 900, 'Contrée perdue', 'Palier Reconquête 3', 'Acte territorial frappé du sceau de la Grande Veilleuse et volontairement laissé incomplet. Frontières, administration, identité et devenir du territoire attendent encore d''être consignés : seule une ancienne dénomination, désormais rayée, rappelle que cette terre appartenait autrefois à d''autres.', 'Le droit permet de reconquérir instantanément une Contrée perdue au choix au bénéfice de Konoha. La communauté dispose ensuite d''une liberté totale pour définir collectivement son nouveau nom, sa description et son illustration. Son coût augmente de 300 XP après chaque reconquête.'),
    ('reconquete-contree-1200', 'Droit de conquête - palier 1200', 1200, 'Contrée perdue', 'Palier Reconquête 4', 'Acte territorial frappé du sceau de la Grande Veilleuse et volontairement laissé incomplet. Frontières, administration, identité et devenir du territoire attendent encore d''être consignés : seule une ancienne dénomination, désormais rayée, rappelle que cette terre appartenait autrefois à d''autres.', 'Le droit permet de reconquérir instantanément une Contrée perdue au choix au bénéfice de Konoha. La communauté dispose ensuite d''une liberté totale pour définir collectivement son nouveau nom, sa description et son illustration. Son coût augmente de 300 XP après chaque reconquête.'),
    ('jeton-reroll-ft', 'Jeton FT', 50, 'Fiche technique', 'Boutique', 'Jeton métallique frappé sur une face du symbole de Konoha et laissé parfaitement vierge sur l''autre. Une fois brisé, tout ce qui avait été inscrit sur cette seconde face est considéré comme n''ayant jamais existé ; il ne reste plus qu''à recommencer.', 'Le jeton remet intégralement à zéro la Fiche Technique du personnage : Kekkei Genkai, techniques validées, affinité et Kuchiyose. L''XP investi dans ces éléments est restitué après leur suppression. Le coût du jeton est débité après la remise à zéro et augmente après chaque utilisation.'),
    ('condition-rang-c-personnel', 'Fragment historique', 100, 'Progression Histoire', 'Rang C', 'Fragment de papier jauni couvert de quelques lignes dont l''encre semble encore fraîche. Le récit s''interrompt brusquement au milieu d''une phrase, comme si plusieurs pages avaient été arrachées entre ce qui devait être accompli et ce qui advint finalement.', 'Le coupon permet de supprimer une condition nécessaire à l''obtention du Rang C Histoire.'),
    ('condition-rang-b-personnel', 'Fragment historique', 100, 'Progression Histoire', 'Rang B', 'Fragment de papier jauni couvert de quelques lignes dont l''encre semble encore fraîche. Le récit s''interrompt brusquement au milieu d''une phrase, comme si plusieurs pages avaient été arrachées entre ce qui devait être accompli et ce qui advint finalement.', 'Le coupon permet de supprimer une condition nécessaire à l''obtention du Rang B Histoire.'),
    ('condition-rang-a-personnel', 'Feuillet historique', 300, 'Progression Histoire', 'Rang A', 'Feuillet dont les marges sont couvertes de corrections, de ratures et d''annotations laissées par une main inconnue. Certains événements y sont rayés avec tant d''insistance qu''il devient impossible de déterminer ce qui aurait dû se produire avant la conclusion du récit.', 'Le coupon permet de supprimer une condition nécessaire à l''obtention du Rang A Histoire.'),
    ('condition-rang-s-personnel', 'Manuscrit historique', 500, 'Progression Histoire', 'Rang S', 'Page esseulée d''un ouvrage qui n''existe dans aucune bibliothèque. Aucun commencement ne précède les quelques lignes qui y sont inscrites, aucune justification n''accompagne leur conclusion. L''Histoire semble simplement avoir accepté qu''il en soit ainsi.', 'Le coupon permet de supprimer une condition nécessaire à l''obtention du Rang S Histoire.'),
    ('condition-rang-d-clanique', 'Registre clanique', 100, 'Progression clanique', 'Rang D', 'Petit registre relié par une cordelette où se succèdent noms, naissances, filiations et quelques faits dignes d''être conservés. Certaines entrées ont disparu avec le temps ; suffisamment pour que la mémoire du Clan puisse combler les blancs.', 'Le registre permet de supprimer une condition nécessaire à l''obtention du Rang D pour le Clan.'),
    ('condition-rang-c-clanique', 'Sceau clanique', 250, 'Progression clanique', 'Rang C', 'Sceau frappé des armoiries du Clan. Son manche porte les marques de propriétaires successifs et sa matrice, usée par les années, continue pourtant d''imprimer le même emblème avec une remarquable netteté.', 'Le sceau permet de supprimer une condition nécessaire à l''obtention du Rang C pour le Clan.'),
    ('condition-rang-b-clanique', 'Chronique clanique', 500, 'Progression clanique', 'Rang B', 'Rouleau généalogique dont les ramifications dépassent largement celles d''une simple famille. Alliances, exploits, querelles, territoires, serments et personnages illustres s''y accumulent jusqu''à former les premières pages d''une véritable histoire commune.', 'La chronique permet de supprimer une condition nécessaire à l''obtention du Rang B pour le Clan.'),
    ('condition-rang-a-clanique', 'Reliquaire clanique', 750, 'Progression clanique', 'Rang A', 'Coffret cérémoniel transmis entre les générations et conservé à l''écart des possessions ordinaires du Clan. Son contenu importe moins que les noms de ceux qui l''ont autrefois possédé : chefs, héros, fondateurs et figures dont les actes ont durablement façonné la lignée.', 'Le reliquaire permet de supprimer une condition nécessaire à l''obtention du Rang A pour le Clan.'),
    ('condition-rang-s-clanique', 'Testament clanique', 1000, 'Progression clanique', 'Rang S', 'Document sans âge portant les volontés attribuées aux premiers représentants du Clan. Les noms qu''il contient appartiennent désormais aux légendes et les événements qu''il rapporte se confondent avec les origines mêmes de la lignée. À son terme demeure un espace vierge, laissé aux générations suffisamment grandes pour prétendre écrire la suite.', 'Le testament permet de supprimer une condition nécessaire à l''obtention du Rang S pour le Clan.'),
    ('condition-rang-d-communautaire', 'Attestation de service', 250, 'Progression Village', 'Rang D', 'Document administratif frappé du sceau de Konoha et délivré aux habitants dont les services rendus au Village méritent d''être consignés. Quelques lignes suffisent parfois pour transformer une contribution ordinaire en mérite officiellement reconnu.', 'L''attestation permet de supprimer une condition nécessaire à l''obtention du Rang D pour le Village.'),
    ('condition-rang-c-communautaire', 'Lettre de recommandation', 500, 'Progression Village', 'Rang C', 'Lettre officielle rédigée et contresignée par une autorité de Konoha. Elle témoigne des services accomplis par son détenteur et engage suffisamment la réputation de son signataire pour que son nom commence à circuler au-delà de son entourage immédiat.', 'La lettre permet de supprimer une condition nécessaire à l''obtention du Rang C pour le Village.'),
    ('condition-rang-b-communautaire', 'Médaille de Konoha', 1000, 'Progression Village', 'Rang B', 'Décoration décernée au nom du Village pour récompenser les services remarquables accomplis en faveur de la Grande Veilleuse. Son revers porte le nom de son détenteur, ainsi que la date de son attribution.', 'La médaille permet de supprimer une condition nécessaire à l''obtention du Rang B pour le Village.'),
    ('condition-rang-a-communautaire', 'Décret honorifique', 1500, 'Progression Village', 'Rang A', 'Acte officiel portant le sceau des plus hautes institutions de Konoha. Conservé dans les registres du Village, il reconnaît publiquement la contribution exceptionnelle de son détenteur à la Grande Veilleuse et inscrit ses accomplissements dans sa mémoire institutionnelle.', 'Le décret permet de supprimer une condition nécessaire à l''obtention du Rang A pour le Village.'),
    ('condition-rang-s-communautaire', 'Monument commémoratif', 2000, 'Progression Village', 'Rang S', 'Droit accordé de faire graver un nom parmi ceux que Konoha refuse de laisser disparaître. Pierre, stèle, statue ou mémorial en conserve la trace dans l''espace même de la Grande Veilleuse : le Village se charge désormais de se souvenir.', 'Le monument permet de supprimer une condition nécessaire à l''obtention du Rang S pour le Village.'),
    ('promotion-chunin', 'Ordre de promotion Chûnin', 90, 'Grade', 'Promotion', 'Document officiel délivré par l''administration militaire de Konoha et frappé du sceau de l''autorité compétente. Quelques lignes y constatent l''aptitude du Shinobi à dépasser les fonctions subalternes et à exercer les responsabilités attachées au grade supérieur.', 'L''ordre entraîne automatiquement la promotion de son détenteur au grade de Chûnin.'),
    ('promotion-jonin', 'Ordre de promotion Jōnin', 150, 'Grade', 'Promotion', 'Document officiel réservé aux Shinobi dont l''expérience justifie l''accès aux plus hautes fonctions ordinaires de la hiérarchie militaire. Nominatif, daté et contresigné, il consigne définitivement le nouveau grade de son détenteur dans les registres de Konoha.', 'L''ordre entraîne automatiquement la promotion de son détenteur au grade de Jōnin.'),
    ('changer-bonus-genin', 'Livret Genin', 5, 'Bonus de grade', 'Genin', 'Petit carnet réglementaire remis aux Genin de Konoha. Il rassemble leur affectation, leurs aptitudes déclarées et les principales informations retenues par l''administration militaire à leur sujet.', 'Le livret permet de remplacer la récompense Genin par une autre.'),
    ('changer-bonus-chunin', 'Dossier Chûnin', 10, 'Bonus de grade', 'Chûnin', 'Dossier individuel consignant le parcours d''un Chûnin, ses compétences reconnues et les fonctions auxquelles son profil le destine. Plusieurs rubriques demeurent amendables à mesure que sa carrière évolue.', 'Le dossier permet de remplacer la récompense Chûnin par une autre.'),
    ('changer-bonus-jonin', 'Brevet Jōnin', 20, 'Bonus de grade', 'Jōnin', 'Brevet militaire attestant des compétences reconnues à un Jōnin et des prérogatives qui en découlent. Les mentions qui y figurent déterminent la manière dont Konoha entend employer son expertise sur le terrain.', 'Le brevet permet de remplacer la récompense Jōnin par une autre.'),
    ('changer-bonus-sannin', 'Patente Sannin', 30, 'Bonus de grade', 'Sannin', 'Acte exceptionnel portant le nom, les qualités et les prérogatives reconnues à l''un des plus éminents Shinobi de Konoha. Sa modification exige que l''institution redéfinisse officiellement ce pour quoi elle reconnaît son détenteur.', 'La patente permet de remplacer la récompense Sannin par une autre.'),
    ('mutation-corps-special', 'Ordre de mutation', 20, 'Corps Spécial', 'Grade conservé', 'Feuillet administratif portant simultanément les marques du Corps quitté et de celui rejoint. Il constate le transfert d''affectation du Shinobi sans remettre en cause le grade acquis au cours de son service.', 'L''ordre permet d''intégrer un autre Corps Spécial tout en conservant son Grade actuel.'),
    ('cadeau-mystere', 'Cadeau mystère', 30, 'Surprise', 'Mystère', 'Petit paquet soigneusement emballé dont aucun signe extérieur ne permet de deviner le contenu. Son poids, sa forme et les quelques bruits qu''il produit lorsqu''on le manipule n''offrent guère davantage d''indices. Il faudra l''ouvrir pour découvrir si Destinée s''est montrée généreuse.', 'Le paquet contient une récompense déterminée aléatoirement parmi l''intégralité des récompenses de la Boutique, y compris celles du Marché Noir.'),
    ('titre-personnalise', 'Fait d''armes', 50, 'Titre', 'Cosmétique', 'Certains noms finissent par s''accompagner de quelques mots supplémentaires. Une action mémorable, une parole restée dans les esprits, un exploit remarquable ou un événement suffisamment retentissant peut ainsi donner naissance à un surnom que les autres commencent à employer.', 'Permet de soumettre un Titre personnalisé inspiré des hauts faits, actions ou paroles du personnage.'),
    ('reroll-trame', 'Fil du Destin', 100, 'Trame', 'Service narratif', 'Fin cordon rouge dont les deux extrémités semblent se prolonger au-delà de ce que l''œil peut suivre. Il suffit parfois de tirer sur un fil différent pour découvrir que les événements auraient pu conduire ailleurs.', 'Permet d''obtenir une Trame si aucune n''a été choisie lors de la présentation, ou de remplacer la Trame actuellement possédée par une autre.'),
    ('pnj-itinerant', 'Bouteille à la mer', 150, 'PNJ', 'Service narratif', 'Bouteille de verre contenant un message dont l''encre s''est presque entièrement effacée durant son voyage. Aucun nom, aucune provenance et aucune destination n''y sont encore lisibles. Pourtant, quelqu''un finira nécessairement par trouver son chemin jusqu''à vous.', 'Provoque l''apparition d''un PNJ itinérant dans un RP du personnage.')
) AS data("itemKey", "name", "costXp", "resource", "rankHint", "description", "effect")
WHERE item."itemKey" = data."itemKey";

